selector_to_html = {"a[href=\"#id12\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">5. \u505c\u6b62\u670d\u52a1<a class=\"headerlink\" href=\"#id12\" title=\"Link to this heading\">#</a></h3><p>\u8fd4\u56de\u7ec8\u7aef A\uff0c\u6309 <code class=\"docutils literal notranslate\"><span class=\"pre\">Ctrl-C</span></code>\uff0c\u7b49\u5f85 API server\u3001EngineCore \u548c worker \u9000\u51fa\u3002</p>", "a[href=\"#flaggems-w4a8\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1. \u6267\u884c FlagGems W4A8 \u6570\u503c\u6d4b\u8bd5<a class=\"headerlink\" href=\"#flaggems-w4a8\" title=\"Link to this heading\">#</a></h3><p>\u672c\u6587\u5bf9\u5e94 commit \u5728 Mac M5 Pro \u4e0a\u7684\u7ed3\u679c\u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">7</span> <span class=\"pre\">passed</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">0</span> <span class=\"pre\">skipped</span></code>\u3002\u6d4b\u8bd5\u4f1a\u6267\u884c Triton W4A8-G128 kernel\uff0c\u5e76\u4e0e PyTorch \u53c2\u8003\u5b9e\u73b0\u6bd4\u8f83\uff1b\u5982\u679c\u5168\u90e8 skip\uff0c\u4e0d\u80fd\u7b97\u901a\u8fc7\u3002</p>", "a[href=\"#id6\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2. \u4e0b\u8f7d\u5e76\u56fa\u5b9a\u6e90\u7801\u7248\u672c<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">#</a></h3><p>\u9010\u9879\u786e\u8ba4\u5b9e\u9645 checkout\uff1a</p>", "a[href=\"#id15\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u63d2\u4ef6\u6ca1\u6709\u52a0\u8f7d<a class=\"headerlink\" href=\"#id15\" title=\"Link to this heading\">#</a></h3><p>\u68c0\u67e5 entry point\uff1a</p>", "a[href=\"#flaggems-vllm-plugin-fl\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">6. \u5b89\u88c5 FlagGems \u548c vllm-plugin-FL<a class=\"headerlink\" href=\"#flaggems-vllm-plugin-fl\" title=\"Link to this heading\">#</a></h3><p>ARM CPU \u63a5\u5165\u662f Python \u8def\u5f84\uff0c\u4e0d\u9700\u8981\u8bbe\u7f6e <code class=\"docutils literal notranslate\"><span class=\"pre\">VLLM_VENDOR=arm</span></code>\u3002\u5982\u679c\u5f53\u524d shell \u7ee7\u627f\u8fc7\u5176\u4ed6\u786c\u4ef6\u540e\u7aef\u7684\u914d\u7f6e\uff0c\u5e94\u5148\u6e05\u9664\u5b83\u3002</p>", "a[href=\"#id10\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3. \u542f\u52a8\u6587\u672c\u670d\u52a1<a class=\"headerlink\" href=\"#id10\" title=\"Link to this heading\">#</a></h3><p>\u5728\u7ec8\u7aef A \u6267\u884c\uff1a</p>", "a[href=\"#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5b89\u88c5\u6d41\u7a0b<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2><p>\u4ee5\u4e0b\u547d\u4ee4\u4f7f\u7528\u4e00\u4e2a\u5168\u65b0\u7684\u5de5\u4f5c\u76ee\u5f55\uff0c\u907f\u514d\u52a0\u8f7d\u7cfb\u7edf\u4e2d\u5df2\u6709\u7684 vLLM\u3001Triton\u3001FlagGems \u6216\u63d2\u4ef6\u3002</p>", "a[href=\"#id17\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u5185\u5b58\u4e0d\u8db3<a class=\"headerlink\" href=\"#id17\" title=\"Link to this heading\">#</a></h3><p>\u672c\u6587\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">VLLM_CPU_KVCACHE_SPACE=1</span></code> \u4e3a 512-token\u3001Batch=1 smoke test \u5206\u914d\u56fa\u5b9a\u7684 1 GiB KV cache\u3002\u5982\u679c\u4fee\u6539\u4e0a\u4e0b\u6587\u957f\u5ea6\u6216\u5e76\u53d1\u6570\uff0c\u5e94\u6839\u636e\u542f\u52a8\u65e5\u5fd7\u91cd\u65b0\u8c03\u6574\uff1b\u5982\u679c\u6a21\u578b\u6743\u91cd\u672c\u8eab\u65e0\u6cd5\u5b8c\u6574\u52a0\u8f7d\uff0c\u589e\u52a0 KV cache \u4e0d\u4f1a\u89e3\u51b3\u95ee\u9898\u3002</p>", "a[href=\"#id9\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6d4b\u8bd5\u6267\u884c\u6d41\u7a0b<a class=\"headerlink\" href=\"#id9\" title=\"Link to this heading\">#</a></h2><p>\u5efa\u8bae\u6309\u4ee5\u4e0b\u987a\u5e8f\u6d4b\u8bd5\u3002\u524d\u4e24\u6b65\u7528\u4e8e\u786e\u8ba4 kernel \u548c\u63d2\u4ef6\u63a5\u53e3\uff0c\u4e0d\u80fd\u53ea\u7528\u4e00\u6b21\u6a21\u578b\u751f\u6210\u66ff\u4ee3\u3002</p>", "a[href=\"#id16\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u9996\u6b21\u8bf7\u6c42\u957f\u65f6\u95f4\u6ca1\u6709\u8fd4\u56de<a class=\"headerlink\" href=\"#id16\" title=\"Link to this heading\">#</a></h3><p>\u5148\u68c0\u67e5 worker \u662f\u5426\u4ecd\u5728\u8fd0\u884c\u548c\u5360\u7528 CPU\uff1b\u9996\u6b21 Triton/LLVM JIT \u53ef\u80fd\u8017\u65f6\u6570\u5206\u949f\u3002\u5982\u679c\u670d\u52a1\u7aef\u5df2\u7ecf\u8f93\u51fa\u5f02\u5e38\uff0c\u5e94\u4ee5\u5f02\u5e38\u4e3a\u51c6\uff0c\u4e0d\u80fd\u5c06 ABI \u4e0d\u5339\u914d\u3001\u7f3a\u5c11\u52a8\u6001\u5e93\u3001undefined symbol \u6216\u67b6\u6784\u9519\u8bef\u89e3\u91ca\u4e3a\u201c\u4ecd\u5728\u7f16\u8bd1\u201d\u3002</p>", "a[href=\"run-inference-task.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u8fd0\u884c\u63a8\u7406\u4efb\u52a1<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p><a class=\"reference internal\" href=\"install.html\"><span class=\"std std-doc\">\u5b89\u88c5</span></a>\u597d vLLM \u548c vllm-plugin-FL \u540e\uff0c\u60a8\u53ef\u4ee5\u901a\u8fc7\u4e24\u79cd\u65b9\u5f0f\u8fd0\u884c\u63a8\u7406\uff1a\u79bb\u7ebf\u6279\u91cf\u63a8\u7406\uff08\u5728 Python \u811a\u672c\u4e2d\u76f4\u63a5\u52a0\u8f7d\u6a21\u578b\uff09\u6216\u670d\u52a1\u63a8\u7406\uff08\u542f\u52a8 API \u670d\u52a1\u5668\u5e76\u53d1\u9001\u8bf7\u6c42\uff09\u3002\u8bf7\u9009\u62e9\u9002\u5408\u60a8\u7528\u4f8b\u7684\u65b9\u5f0f\u3002</p>", "a[href=\"#python\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1. \u521b\u5efa Python \u73af\u5883<a class=\"headerlink\" href=\"#python\" title=\"Link to this heading\">#</a></h3><p>\u9884\u671f Python \u4e3a 3.11\uff0c\u67b6\u6784\u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">arm64</span></code> \u6216 <code class=\"docutils literal notranslate\"><span class=\"pre\">aarch64</span></code>\u3002</p>", "a[href=\"#flagtree-cpu-triton-3-7-2\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4. \u6784\u5efa flagtree-cpu / Triton 3.7.2<a class=\"headerlink\" href=\"#flagtree-cpu-triton-3-7-2\" title=\"Link to this heading\">#</a></h3><p>\u9a8c\u8bc1\u5f53\u524d Python \u52a0\u8f7d\u7684\u662f\u521a\u5b89\u88c5\u7684 flagtree-cpu\uff1a</p>", "a[href=\"#vllm-0-24-0-cpu\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">5. \u6784\u5efa vLLM 0.24.0 CPU<a class=\"headerlink\" href=\"#vllm-0-24-0-cpu\" title=\"Link to this heading\">#</a></h3><p>\u9a8c\u8bc1\u7248\u672c\u4e0e\u6784\u5efa\u7c7b\u578b\uff1a</p>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u73af\u5883\u914d\u7f6e<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><h3>\u8fd0\u884c\u524d\u68c0\u67e5<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h3><p>\u5148\u786e\u8ba4\u4e3b\u673a\u67b6\u6784\u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">arm64</span></code> \u6216 <code class=\"docutils literal notranslate\"><span class=\"pre\">aarch64</span></code>\uff1a</p>", "a[href=\"#cpu-platform\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">7. \u9a8c\u8bc1\u63d2\u4ef6\u548c CPU platform<a class=\"headerlink\" href=\"#cpu-platform\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">VLLM_PLUGINS</span></code> \u662f vLLM \u5b98\u65b9\u63d0\u4f9b\u7684\u63d2\u4ef6\u8fc7\u6ee4\u53d8\u91cf\u3002<code class=\"docutils literal notranslate\"><span class=\"pre\">VLLM_PLUGINS=fl</span></code> \u8868\u793a\u53ea\u52a0\u8f7d\u540d\u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">fl</span></code> \u7684\u5df2\u5b89\u88c5\u63d2\u4ef6\uff1b\u5b83\u4e0d\u8d1f\u8d23\u8bc6\u522b ARM\uff0c\u4e5f\u4e0d\u80fd\u66ff\u4ee3 <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGGEMS_VENDOR=arm</span></code>\u3002</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGGEMS_VENDOR=arm</span></code> \u5fc5\u987b\u5728\u5f53\u524d\u8fdb\u7a0b\u7b2c\u4e00\u6b21\u5bfc\u5165 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">vllm_fl</span></code> \u6216 <code class=\"docutils literal notranslate\"><span class=\"pre\">vllm</span></code> \u4e4b\u524d\u8bbe\u7f6e\uff1a</p>", "a[href=\"#id7\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3. \u5b89\u88c5 Python \u4f9d\u8d56<a class=\"headerlink\" href=\"#id7\" title=\"Link to this heading\">#</a></h3><p>\u5efa\u7acb\u7ea6\u675f\u6587\u4ef6\uff1a</p>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u8f6f\u4ef6\u73af\u5883<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><p>\u76f8\u5173\u8bc4\u5ba1\u94fe\u63a5\uff1a</p>", "a[href=\"#cpuplatform\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u5e73\u53f0\u4e0d\u662f CpuPlatform<a class=\"headerlink\" href=\"#cpuplatform\" title=\"Link to this heading\">#</a></h3><p>Linux \u4e0a\u786e\u8ba4\u5b89\u88c5\u7684\u662f vLLM CPU build\uff1bARM+GPU/NPU \u4e3b\u673a\u8fd8\u5e94\u786e\u8ba4\u6ca1\u6709\u9009\u62e9\u5176\u4ed6 device plugin\u3002\u4e0d\u8981\u4f2a\u9020 <code class=\"docutils literal notranslate\"><span class=\"pre\">platform.machine()</span></code> \u6216\u5f3a\u5236 monkey-patch <code class=\"docutils literal notranslate\"><span class=\"pre\">current_platform</span></code> \u7ed5\u8fc7\u68c0\u67e5\u3002</p>", "a[href=\"#id14\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5e38\u89c1\u95ee\u9898<a class=\"headerlink\" href=\"#id14\" title=\"Link to this heading\">#</a></h2><h3>\u63d2\u4ef6\u6ca1\u6709\u52a0\u8f7d<a class=\"headerlink\" href=\"#id15\" title=\"Link to this heading\">#</a></h3><p>\u68c0\u67e5 entry point\uff1a</p>", "a[href=\"#arm-cpu-empty-vllm0-24-0-vllm-plugin-fl\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">ARM CPU + empty vllm0.24.0+vllm-plugin-FL<a class=\"headerlink\" href=\"#arm-cpu-empty-vllm0-24-0-vllm-plugin-fl\" title=\"Link to this heading\">#</a></h1><p>\u672c\u6587\u8bf4\u660e\u5982\u4f55\u5728 ARM64 CPU \u4e0a\u4ece\u6e90\u7801\u5b89\u88c5 vLLM 0.24.0\u3001vllm-plugin-FL\u3001FlagGems \u548c flagtree-cpu\uff0c\u5e76\u4f7f\u7528 MiniCPM-2B \u5b8c\u6210\u4e00\u6b21\u8f7b\u91cf\u6587\u672c\u63a8\u7406\u9a8c\u8bc1\u3002</p><p>vllm-plugin-FL \u8d1f\u8d23 vLLM \u63d2\u4ef6\u6ce8\u518c\u3001ARM CPU platform \u9009\u62e9\u3001packed checkpoint \u63a5\u5165\u4ee5\u53ca Qwen GDN \u7684 CPU \u517c\u5bb9\u5904\u7406\uff1bFlagGems \u63d0\u4f9b W4A8-G128 \u6743\u91cd\u6253\u5305\u548c Triton kernel\uff1bflagtree-cpu \u5c06 Triton \u7a0b\u5e8f\u7f16\u8bd1\u5230 ARM CPU\u3002</p>", "a[href=\"#id13\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6d4b\u8bd5\u547d\u4ee4<a class=\"headerlink\" href=\"#id13\" title=\"Link to this heading\">#</a></h2><h3>eager \u6a21\u5f0f\uff08\u5df2\u9a8c\u8bc1\uff09<a class=\"headerlink\" href=\"#eager\" title=\"Link to this heading\">#</a></h3><p>\u672c\u6587\u201c\u6d4b\u8bd5\u6267\u884c\u6d41\u7a0b\u201d\u4e2d\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">vllm</span> <span class=\"pre\">serve</span></code> \u547d\u4ee4\u5373\u4e3a\u5f53\u524d\u9a8c\u8bc1\u547d\u4ee4\u30022026-09-04 \u7684 Mac \u590d\u9a8c\u4f7f\u7528 vLLM \u6e90\u7801 commit <code class=\"docutils literal notranslate\"><span class=\"pre\">ee0da84a</span></code>\u3001FlagGems <code class=\"docutils literal notranslate\"><span class=\"pre\">1fda4b11</span></code>\u3001vllm-plugin-FL <code class=\"docutils literal notranslate\"><span class=\"pre\">58a690b</span></code>\u3001Qwen3-1.7B BF16\u3001Batch=1 \u548c <code class=\"docutils literal notranslate\"><span class=\"pre\">--enforce-eager</span></code>\u3002\u670d\u52a1\u52a0\u8f7d 2 \u4e2a safetensors \u5206\u7247\uff0c\u65e5\u5fd7\u786e\u8ba4 CPU KV cache \u56fa\u5b9a\u4e3a 1 GiB\uff1b<code class=\"docutils literal notranslate\"><span class=\"pre\">/health</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">/v1/models</span></code> \u548c\u6d41\u5f0f <code class=\"docutils literal notranslate\"><span class=\"pre\">/v1/chat/completions</span></code> \u8bf7\u6c42\u5747\u8fd4\u56de HTTP 200\uff0c\u5ba2\u6237\u7aef\u6536\u5230 16 \u4e2a\u975e\u7a7a\u6587\u672c token\u3002</p>", "a[href=\"#id11\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4. \u6267\u884c\u6587\u672c\u8bf7\u6c42<a class=\"headerlink\" href=\"#id11\" title=\"Link to this heading\">#</a></h3><p>\u5728\u7ec8\u7aef B \u5148\u68c0\u67e5\u5065\u5eb7\u72b6\u6001\u548c\u6a21\u578b\u540d\uff1a</p>", "a[href=\"#id8\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6a21\u578b\u51c6\u5907<a class=\"headerlink\" href=\"#id8\" title=\"Link to this heading\">#</a></h2><p>\u672c\u6587\u4f7f\u7528 ModelScope \u4e0a\u7684 MiniCPM-2B\u3002\u4e0b\u8f7d\u547d\u4ee4\u4f7f\u7528 ModelScope 1.39.1 CLI\uff1a</p>", "a[href=\"#macos-openmp\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">macOS \u627e\u4e0d\u5230 OpenMP<a class=\"headerlink\" href=\"#macos-openmp\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#macos\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">macOS<a class=\"headerlink\" href=\"#macos\" title=\"Link to this heading\">#</a></h3><p>macOS \u9700\u8981 Apple Silicon\u3001Xcode Command Line Tools\u3001Homebrew \u548c Python 3.11\uff1a</p>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u786c\u4ef6\u73af\u5883<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#flaggems\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">FlagGems \u5bfc\u5165\u5931\u8d25<a class=\"headerlink\" href=\"#flaggems\" title=\"Link to this heading\">#</a></h3><p>\u5f53\u524d\u63d2\u4ef6\u7684\u516c\u5171\u5de5\u5177\u6a21\u5757\u4f1a\u5bfc\u5165 FlagGems\u3002\u7f3a\u5c11 FlagGems \u65f6\uff0c<code class=\"docutils literal notranslate\"><span class=\"pre\">fl</span></code> entry point \u65e0\u6cd5\u5b8c\u6574\u52a0\u8f7d\uff0c\u672c\u6587\u7684 W4A8 checkpoint \u4e5f\u65e0\u6cd5\u8fd0\u884c\u3002\u68c0\u67e5\u5b9e\u9645\u8def\u5f84\uff1a</p>", "a[href=\"#id2\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u8fd0\u884c\u524d\u68c0\u67e5<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h3><p>\u5148\u786e\u8ba4\u4e3b\u673a\u67b6\u6784\u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">arm64</span></code> \u6216 <code class=\"docutils literal notranslate\"><span class=\"pre\">aarch64</span></code>\uff1a</p>", "a[href=\"#arm-gpu-npu\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">ARM \u4e3b\u673a\u540c\u65f6\u5b89\u88c5 GPU \u6216 NPU \u65f6\u7684\u884c\u4e3a<a class=\"headerlink\" href=\"#arm-gpu-npu\" title=\"Link to this heading\">#</a></h2><p>CPU \u67b6\u6784\u662f ARM64\uff0c\u4e0d\u4ee3\u8868 vLLM \u4e00\u5b9a\u9009\u62e9 CPU backend\u3002\u63d2\u4ef6\u53ea\u5728\u4e0b\u5217\u4e24\u4e2a\u6761\u4ef6\u540c\u65f6\u6210\u7acb\u65f6\u6ce8\u518c vLLM CPU platform\uff0c\u5e76\u5b89\u88c5 GDN \u517c\u5bb9\u5904\u7406\uff1a</p>", "a[href=\"#vllm-plugin-fl-arm\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2. \u6267\u884c vllm-plugin-FL ARM \u63a5\u53e3\u6d4b\u8bd5<a class=\"headerlink\" href=\"#vllm-plugin-fl-arm\" title=\"Link to this heading\">#</a></h3><p>\u672c\u6587\u5bf9\u5e94 commit \u5728 Mac M5 Pro \u4e0a\u7684\u7ed3\u679c\u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">16</span> <span class=\"pre\">passed</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">0</span> <span class=\"pre\">skipped</span></code>\u3002\u5176\u4e2d\u5305\u62ec ARM CPU platform \u6ce8\u518c\u3001ARM \u4e3b\u673a\u4e0a GPU backend \u9694\u79bb\u3001GDN patch \u5e42\u7b49\u6027\u4ee5\u53ca packed W4A8 \u53c2\u6570\u5951\u7ea6\u3002</p>", "a[href=\"#linux-arm64\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Linux ARM64<a class=\"headerlink\" href=\"#linux-arm64\" title=\"Link to this heading\">#</a></h3><p>\u4ee5\u4e0b\u4f9d\u8d56\u547d\u4ee4\u9002\u7528\u4e8e Debian/Ubuntu\u3002vLLM 0.24.0 \u7684 ARM CPU \u6e90\u7801\u6784\u5efa\u8981\u6c42 NEON\uff0c\u5e76\u5efa\u8bae\u4f7f\u7528 GCC/G++ 12.3 \u6216\u66f4\u9ad8\u7248\u672c\u3002</p>", "a[href=\"#eager\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">eager \u6a21\u5f0f\uff08\u5df2\u9a8c\u8bc1\uff09<a class=\"headerlink\" href=\"#eager\" title=\"Link to this heading\">#</a></h3><p>\u672c\u6587\u201c\u6d4b\u8bd5\u6267\u884c\u6d41\u7a0b\u201d\u4e2d\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">vllm</span> <span class=\"pre\">serve</span></code> \u547d\u4ee4\u5373\u4e3a\u5f53\u524d\u9a8c\u8bc1\u547d\u4ee4\u30022026-09-04 \u7684 Mac \u590d\u9a8c\u4f7f\u7528 vLLM \u6e90\u7801 commit <code class=\"docutils literal notranslate\"><span class=\"pre\">ee0da84a</span></code>\u3001FlagGems <code class=\"docutils literal notranslate\"><span class=\"pre\">1fda4b11</span></code>\u3001vllm-plugin-FL <code class=\"docutils literal notranslate\"><span class=\"pre\">58a690b</span></code>\u3001Qwen3-1.7B BF16\u3001Batch=1 \u548c <code class=\"docutils literal notranslate\"><span class=\"pre\">--enforce-eager</span></code>\u3002\u670d\u52a1\u52a0\u8f7d 2 \u4e2a safetensors \u5206\u7247\uff0c\u65e5\u5fd7\u786e\u8ba4 CPU KV cache \u56fa\u5b9a\u4e3a 1 GiB\uff1b<code class=\"docutils literal notranslate\"><span class=\"pre\">/health</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">/v1/models</span></code> \u548c\u6d41\u5f0f <code class=\"docutils literal notranslate\"><span class=\"pre\">/v1/chat/completions</span></code> \u8bf7\u6c42\u5747\u8fd4\u56de HTTP 200\uff0c\u5ba2\u6237\u7aef\u6536\u5230 16 \u4e2a\u975e\u7a7a\u6587\u672c token\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
